import { RefObject, useEffect, useRef } from 'react'

/**
 * Calls `handler` when a pointer event lands outside `ref`.
 *
 * Listens on both `mousedown` and `touchstart` rather than `click`, so the
 * handler runs before the element under the pointer can react — the usual
 * reason this hook exists (closing a menu before its trigger toggles again).
 */
export function useClickOutside<T extends HTMLElement>(
  ref: RefObject<T | null>,
  handler: (event: MouseEvent | TouchEvent) => void
): void {
  // Kept in a ref so an inline arrow function passed as `handler` does not
  // tear down and re-attach both listeners on every render.
  const handlerRef = useRef(handler)
  handlerRef.current = handler

  useEffect(() => {
    const onPointerDown = (event: MouseEvent | TouchEvent) => {
      const el = ref.current
      if (!el || el.contains(event.target as Node)) return
      handlerRef.current(event)
    }

    document.addEventListener('mousedown', onPointerDown)
    document.addEventListener('touchstart', onPointerDown)

    return () => {
      document.removeEventListener('mousedown', onPointerDown)
      document.removeEventListener('touchstart', onPointerDown)
    }
  }, [ref])
}

import { RefObject, useLayoutEffect, useState } from 'react'

export interface ElementSize {
  width: number
  height: number
}

/**
 * Tracks an element's rendered width and height.
 *
 * Measures synchronously in a layout effect so the first paint has real
 * numbers, then keeps up to date via `ResizeObserver`.
 */
export function useElementSize<T extends HTMLElement = HTMLElement>(
  ref?: RefObject<T | null>
): ElementSize {
  const [size, setSize] = useState<ElementSize>({ width: 0, height: 0 })

  useLayoutEffect(() => {
    const element = ref?.current
    if (!element) {
      setSize({ width: 0, height: 0 })
      return
    }

    const measure = () => {
      const rect = element.getBoundingClientRect()
      // getBoundingClientRect reports 0 for elements that are laid out but not
      // yet painted; offset/client sizes are the fallbacks that do report.
      const next = {
        width: rect.width || element.offsetWidth || element.clientWidth,
        height: rect.height || element.offsetHeight || element.clientHeight,
      }
      setSize((prev) =>
        prev.width === next.width && prev.height === next.height ? prev : next
      )
    }

    measure()

    // ResizeObserver fires once on observe, which covers the case where the
    // element is measurable only after layout settles.
    const observer = new ResizeObserver(measure)
    observer.observe(element)
    return () => observer.disconnect()
  }, [ref])

  return size
}

import { useEffect, useState } from 'react'

export interface MousePosition {
  x: number | null
  y: number | null
}

/**
 * The pointer's current viewport coordinates, or `null` before the first move.
 *
 * Note this re-renders on every `mousemove`. For anything that only needs the
 * position at a moment in time (a context menu, a drag start), read it from
 * the event instead.
 */
export function useMousePosition(): MousePosition {
  const [position, setPosition] = useState<MousePosition>({ x: null, y: null })

  useEffect(() => {
    const update = (event: MouseEvent) =>
      setPosition({ x: event.clientX, y: event.clientY })

    window.addEventListener('mousemove', update)
    return () => window.removeEventListener('mousemove', update)
  }, [])

  return position
}

import { RefObject, useEffect, useState } from 'react'

/**
 * Makes a ref's current value readable as state.
 *
 * Assigning to `ref.current` does not re-render, so a parent that needs to
 * *render* something derived from a child's `useImperativeHandle` can't just
 * read `ref.current` — on first render it is still null. This mirrors the ref
 * into state so the parent re-renders once the handle is attached.
 *
 * Child effects commit before parent effects, so by the time this effect runs
 * the child's imperative handle is already assigned — no timeout needed.
 */
export function useAccessImperativeHandle<T>(
  ref: RefObject<T | null>
): T | null {
  const [handle, setHandle] = useState<T | null>(null)

  useEffect(() => {
    // Guarded so this only re-renders when the identity actually changes,
    // rather than on every commit.
    setHandle((prev) => (prev === ref.current ? prev : ref.current))
  })

  return handle
}

import { useCallback, useRef, useState } from 'react'

export interface RemainingHeight {
  /** Pixels from the element's top edge to the bottom of the viewport, minus `offset`. */
  height: number
  /** True until the first measurement lands. */
  isLoading: boolean
  /** Attach to the element whose remaining height you want: `<div ref={getHeight}>`. */
  getHeight: (node: HTMLElement | null) => void
  recalculate: () => void
}

/**
 * Measures how much vertical space is left between an element's top edge and
 * the bottom of the viewport — the usual way to size a scroll area that should
 * fill the rest of the page without a fixed height.
 *
 * Watches three things, because any of them can change the answer without the
 * others firing: window resize, the element's own box (ResizeObserver), and
 * structural or style changes in the parent (MutationObserver).
 *
 * Requires React 19: this returns a cleanup function from a callback ref,
 * which earlier versions silently ignore.
 */
export function useRemainingHeight(offset = 0): RemainingHeight {
  const [height, setHeight] = useState(0)
  const [isLoading, setIsLoading] = useState(true)
  const nodeRef = useRef<HTMLElement | null>(null)

  const updateHeight = useCallback(() => {
    if (!nodeRef.current) return
    // Deferred a frame so the measurement reflects the layout after whatever
    // change triggered it, not the one before.
    requestAnimationFrame(() => {
      const node = nodeRef.current
      if (!node) return
      const rect = node.getBoundingClientRect()
      setHeight(Math.max(0, window.innerHeight - rect.top - offset))
      setIsLoading(false)
    })
  }, [offset])

  const getHeight = useCallback(
    (node: HTMLElement | null) => {
      nodeRef.current = node
      if (!node) return

      updateHeight()
      window.addEventListener('resize', updateHeight)

      const resizeObserver = new ResizeObserver(updateHeight)
      const mutationObserver = new MutationObserver(updateHeight)

      resizeObserver.observe(node)
      if (node.parentElement) {
        resizeObserver.observe(node.parentElement)
        mutationObserver.observe(node.parentElement, {
          childList: true,
          subtree: true,
          attributes: true,
          attributeFilter: ['style', 'class'],
        })
      }

      return () => {
        window.removeEventListener('resize', updateHeight)
        resizeObserver.disconnect()
        mutationObserver.disconnect()
      }
    },
    [updateHeight]
  )

  return { height, isLoading, getHeight, recalculate: updateHeight }
}

import { parseAsIndex, parseAsInteger, useQueryStates } from 'nuqs'

export interface PaginationDefaults {
  pageIndex: number
  pageSize: number
}

/**
 * Pagination state stored in the URL rather than component state, so a paged
 * view survives reload and can be shared or linked to.
 *
 * `parseAsIndex` is deliberate: the URL shows a 1-based `?page=1` while the
 * value you read stays 0-based, which is what TanStack Table and most
 * pagination APIs expect.
 *
 * The URL keys are `page` and `perPage`; the state keys are `pageIndex` and
 * `pageSize`, so it drops straight into a TanStack Table `pagination` state.
 */
export function usePaginationQueryState(
  defaultValues: PaginationDefaults = { pageIndex: 0, pageSize: 10 }
) {
  return useQueryStates(
    {
      pageIndex: parseAsIndex.withDefault(defaultValues.pageIndex),
      pageSize: parseAsInteger.withDefault(defaultValues.pageSize),
    },
    {
      urlKeys: { pageIndex: 'page', pageSize: 'perPage' },
    }
  )
}
